// The parts of @builder.io/qwik-city 1.20.1's typings CPR's Qwik plugin relies on; `Loader` is
// declared as `Loader_2` and exported under its public name, as in the real package.
import type { FunctionComponent, Signal } from '@builder.io/qwik';

export declare type RequestEvent = {
  url: URL;
  cacheControl: (options: { maxAge: number }) => void;
  next: () => Promise<void>;
};
export declare type RequestHandler = (event: RequestEvent) => Promise<void> | void;
export declare type DocumentHead = { title?: string };
export declare type StaticGenerateHandler = () => { params: Record<string, string>[] };

declare type Loader_2<RETURN> = {
  (): Signal<RETURN>;
};
export { Loader_2 as Loader };

export declare type ActionStore<RETURN, INPUT> = {
  value: RETURN | undefined;
  submit: (form: INPUT) => Promise<unknown>;
};
export declare type Action<
  RETURN,
  INPUT = Record<string, unknown>,
  OPTIONAL extends boolean = true,
> = {
  (): ActionStore<RETURN, INPUT>;
  readonly __optional?: OPTIONAL;
};

declare type LoaderConstructor = <OBJ>(loader: (event: RequestEvent) => OBJ) => Loader_2<OBJ>;
declare type ActionConstructor = <OBJ>(
  action: (data: Record<string, unknown>, event: RequestEvent) => OBJ,
) => Action<OBJ>;

export declare const routeLoader$: LoaderConstructor;
export declare const routeAction$: ActionConstructor;
export declare const globalAction$: ActionConstructor;
export declare const Link: FunctionComponent<{ href: string }>;
